import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T>
__global__ void __launch_bounds__(64, 16) dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int OwTiles,
    int IH_TILE)
{
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 32;
  constexpr int OW_VEC     = 4;
  constexpr int TILE_OW_THREADS = TILE_OW / OW_VEC;
  constexpr int CcPerBlock = 2;
  constexpr int KChunk     = 8;
  const int tid_x = threadIdx.x; // ow-group local (0..TILE_OW_THREADS-1)
  const int tid_y = threadIdx.y; // oh local
  const int tid   = tid_y * TILE_OW_THREADS + tid_x;
  const int NThreads = TILE_OH * TILE_OW_THREADS;
  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;
  const int ow_tile_idx = blockIdx.x % OwTiles;
  const int oh_tile_idx = blockIdx.x / OwTiles;
  const int oh_tile_base = oh_tile_idx * TILE_OH;
  const int ow_tile_base = ow_tile_idx * TILE_OW;
  const int oh_global = oh_tile_base + tid_y;
  const int ow_local_base = tid_x * OW_VEC;
  int ow_global[OW_VEC];
  #pragma unroll
  for (int v = 0; v < OW_VEC; ++v) {
    ow_global[v] = ow_tile_base + ow_local_base + v;
  }
  const bool oh_valid = (oh_global < Hout);
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(C, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride(K, Int<1>{})
  );
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* sX = reinterpret_cast<T*>(smem_raw);
  T* sW = sX + (size_t)CcPerBlock * IH_TILE * TILE_OW;
  float acc[CcPerBlock][OW_VEC];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < C) bval = (float)B[c];
    #pragma unroll
    for (int v = 0; v < OW_VEC; ++v) acc[cc][v] = bval;
  }
  for (int k0 = 0; k0 < K; k0 += KChunk) {
    const int kchunk_actual = min(KChunk, K - k0);
    const int min_ih = oh_tile_base * stride - padding + k0 * dilation;
    const int total_in = CcPerBlock * IH_TILE * TILE_OW;
    const bool use_vec4 = (stride == 1) && (padding % 4 == 0) && (Win % 4 == 0);
    if (use_vec4) {
      const int total_in_vec = CcPerBlock * IH_TILE * (TILE_OW / 4);
      for (int idx = tid; idx < total_in_vec; idx += NThreads) {
        int cc        = idx / (IH_TILE * (TILE_OW / 4));
        int rem       = idx - cc * (IH_TILE * (TILE_OW / 4));
        int ih_local  = rem / (TILE_OW / 4);
        int ow_vec    = rem - ih_local * (TILE_OW / 4);
        int ow_local0 = ow_vec * 4;
        int c     = c_base + cc;
        int ow_g0 = ow_tile_base + ow_local0;
        int iw_g0 = ow_g0 - padding;
        int ih_g  = min_ih + ih_local;
        float4 val4 = make_float4(0.f, 0.f, 0.f, 0.f);
        if (c < C && ih_g >= 0 && ih_g < H) {
          if (iw_g0 >= 0 && (iw_g0 + 3) < Win && (ow_g0 + 3) < Wout) {
            const float4* src = reinterpret_cast<const float4*>(&mX(c, ih_g, iw_g0));
            val4 = *src;
          } else {
            float tmp0 = 0.f, tmp1 = 0.f, tmp2 = 0.f, tmp3 = 0.f;
            int iw0 = iw_g0, iw1 = iw_g0 + 1, iw2 = iw_g0 + 2, iw3 = iw_g0 + 3;
            int ow0 = ow_g0, ow1 = ow_g0 + 1, ow2 = ow_g0 + 2, ow3 = ow_g0 + 3;
            if (ow0 < Wout && iw0 >= 0 && iw0 < Win) tmp0 = mX(c, ih_g, iw0);
            if (ow1 < Wout && iw1 >= 0 && iw1 < Win) tmp1 = mX(c, ih_g, iw1);
            if (ow2 < Wout && iw2 >= 0 && iw2 < Win) tmp2 = mX(c, ih_g, iw2);
            if (ow3 < Wout && iw3 >= 0 && iw3 < Win) tmp3 = mX(c, ih_g, iw3);
            val4 = make_float4(tmp0, tmp1, tmp2, tmp3);
          }
        }
        int base_idx = cc * (IH_TILE * TILE_OW) + ih_local * TILE_OW + ow_local0;
        *reinterpret_cast<float4*>(&sX[base_idx]) = val4;
      }
    } else {
      for (int idx = tid; idx < total_in; idx += NThreads) {
        int cc  = idx / (IH_TILE * TILE_OW);
        int rem = idx - cc * (IH_TILE * TILE_OW);
        int ih_local = rem / TILE_OW;
        int ow_local = rem - ih_local * TILE_OW;
        int c    = c_base + cc;
        int ow_g = ow_tile_base + ow_local;
        int iw_g = ow_g * stride - padding;
        int ih_g = min_ih + ih_local;
        T val = T(0);
        if (c < C && ow_g < Wout && iw_g >= 0 && iw_g < Win && ih_g >= 0 && ih_g < H) {
          val = mX(c, ih_g, iw_g);
        }
        sX[idx] = val;
      }
    }
    const int total_w = CcPerBlock * KChunk;
    for (int idx = tid; idx < total_w; idx += NThreads) {
      int cc = idx / KChunk;
      int kk = idx - cc * KChunk;
      int c  = c_base + cc;
      int k_global = k0 + kk;
      T wval = T(0);
      if (c < C && k_global < K) wval = mW(c, k_global);
      sW[idx] = wval;
    }
    __syncthreads();
    if (oh_valid) {
      #pragma unroll
      for (int kk = 0; kk < KChunk; ++kk) {
        if (kk >= kchunk_actual) break;
        int ih_local_index = tid_y * stride + kk * dilation;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int c = c_base + cc;
          if (c >= C) continue;
          float wval = (float)sW[cc * KChunk + kk];
          const T* sX_row = &sX[cc * IH_TILE * TILE_OW + ih_local_index * TILE_OW + ow_local_base];
          const float4 xval4 = *reinterpret_cast<const float4*>(sX_row);
          acc[cc][0] += xval4.x * wval;
          acc[cc][1] += xval4.y * wval;
          acc[cc][2] += xval4.z * wval;
          acc[cc][3] += xval4.w * wval;
        }
      }
    }
    __syncthreads();
  }
  if (oh_valid) {
    const bool vec_store_ok = (stride == 1) && (Wout % 4 == 0) && (ow_global[0] < Wout);
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      if (c >= C) continue;
      if (vec_store_ok) {
        float4 val4 = make_float4(acc[cc][0], acc[cc][1], acc[cc][2], acc[cc][3]);
        float4* dst = reinterpret_cast<float4*>(&mY(c, oh_global, ow_global[0]));
        *dst = val4;
      } else {
        #pragma unroll
        for (int v = 0; v < OW_VEC; ++v) {
          if (ow_global[v] < Wout) {
            mY(c, oh_global, ow_global[v]) = static_cast<T>(acc[cc][v]);
          }
        }
      }
    }
  }
}
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for (kernel_width=1)");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (1 - 1) - 1) / stride + 1; // kw=1
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C, Hout, Wout}, x.options());
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 32;
  constexpr int CcPerBlock = 2;
  constexpr int KChunk     = 8;
  const int OhTiles = (int)((Hout + TILE_OH - 1) / TILE_OH);
  const int OwTiles = (int)((Wout + TILE_OW - 1) / TILE_OW);
  dim3 block(TILE_OW / 4, TILE_OH);
  dim3 grid(
      (unsigned)(OhTiles * OwTiles),
      (unsigned)((C + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );
  const int KChunkEff = (K < KChunk) ? (int)K : KChunk;
  const int IH_TILE = (TILE_OH - 1) * stride + (KChunkEff - 1) * dilation + 1;
  size_t smem_size = (size_t)CcPerBlock * IH_TILE * TILE_OW * sizeof(float)
                    + (size_t)CcPerBlock * KChunk * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_size > 48 * 1024) {
    cudaFuncSetAttribute(dwconv2d_k1_kernel<float>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_size);
  }
  dwconv2d_k1_kernel<float><<<grid, block, smem_size, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)K, (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout,
      OwTiles,
      IH_TILE
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

dwconv2d_ext = load_inline(
    name="cute_dwconv2d_k1_ext_v2",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with vertical asymmetric kernel (kernel_size x 1),
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        # Depthwise: groups = in_channels, out_channels = in_channels
        C = self.in_channels
        K = self.kernel_size
        # Weight shape matches PyTorch depthwise layout: [C_out, C_in/groups, Kh, Kw] with groups=C => [C,1,K,1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = dwconv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size  # depthwise per-channel fan_in equals kernel_size along H (Kw=1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

