import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T>
__global__ void __launch_bounds__(64, 8) dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int OwTiles,
    int IH_TILE)
{
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 32;
  constexpr int OW_VEC     = 4;
  constexpr int TILE_OW_THREADS = TILE_OW / OW_VEC;
  constexpr int CcPerBlock = 2;
  constexpr int KChunk     = 8;
  const int tid_x = threadIdx.x; // ow-group local (0..TILE_OW_THREADS-1)
  const int tid_y = threadIdx.y; // oh local
  const int tid   = tid_y * TILE_OW_THREADS + tid_x;
  const int NThreads = TILE_OH * TILE_OW_THREADS;
  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;
  const int ow_tile_idx = blockIdx.x % OwTiles;
  const int oh_tile_idx = blockIdx.x / OwTiles;
  const int oh_tile_base = oh_tile_idx * TILE_OH;
  const int ow_tile_base = ow_tile_idx * TILE_OW;
  const int oh_global = oh_tile_base + tid_y;
  const int ow_local_base = tid_x * OW_VEC;
  int ow_global[OW_VEC];
  #pragma unroll
  for (int v = 0; v < OW_VEC; ++v) {
    ow_global[v] = ow_tile_base + ow_local_base + v;
  }
  const bool oh_valid = (oh_global < Hout);
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(C, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride(K, Int<1>{})
  );
  extern __shared__ __align__(16) unsigned char smem_raw[];
  T* sX = reinterpret_cast<T*>(smem_raw);
  T* sW = sX + (size_t)CcPerBlock * IH_TILE * TILE_OW;
  float acc[CcPerBlock][OW_VEC];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < C) bval = (float)B[c];
    #pragma unroll
    for (int v = 0; v < OW_VEC; ++v) acc[cc][v] = bval;
  }
  for (int k0 = 0; k0 < K; k0 += KChunk) {
    const int kchunk_actual = min(KChunk, K - k0);
    const int min_ih = oh_tile_base * stride - padding + k0 * dilation;
    const int total_in = CcPerBlock * IH_TILE * TILE_OW;
    const bool use_vec4 = (stride == 1) && (padding % 4 == 0) && (Win % 4 == 0);
    if (use_vec4) {
      const int total_in_vec = CcPerBlock * IH_TILE * (TILE_OW / 4);
      for (int idx = tid; idx < total_in_vec; idx += NThreads) {
        int cc        = idx / (IH_TILE * (TILE_OW / 4));
        int rem       = idx - cc * (IH_TILE * (TILE_OW / 4));
        int ih_local  = rem / (TILE_OW / 4);
        int ow_vec    = rem - ih_local * (TILE_OW / 4);
        int ow_local0 = ow_vec * 4;
        int c     = c_base + cc;
        int ow_g0 = ow_tile_base + ow_local0;
        int iw_g0 = ow_g0 - padding;
        int ih_g  = min_ih + ih_local;
        float4 val4 = make_float4(0.f, 0.f, 0.f, 0.f);
        if (c < C && ih_g >= 0 && ih_g < H) {
          if (iw_g0 >= 0 && (iw_g0 + 3) < Win && (ow_g0 + 3) < Wout) {
            const float4* src = reinterpret_cast<const float4*>(&mX(c, ih_g, iw_g0));
            val4 = *src;
          } else {
            float tmp0 = 0.f, tmp1 = 0.f, tmp2 = 0.f, tmp3 = 0.f;
            int iw0 = iw_g0, iw1 = iw_g0 + 1, iw2 = iw_g0 + 2, iw3 = iw_g0 + 3;
            int ow0 = ow_g0, ow1 = ow_g0 + 1, ow2 = ow_g0 + 2, ow3 = ow_g0 + 3;
            if (ow0 < Wout && iw0 >= 0 && iw0 < Win) tmp0 = mX(c, ih_g, iw0);
            if (ow1 < Wout && iw1 >= 0 && iw1 < Win) tmp1 = mX(c, ih_g, iw1);
            if (ow2 < Wout && iw2 >= 0 && iw2 < Win) tmp2 = mX(c, ih_g, iw2);
            if (ow3 < Wout && iw3 >= 0 && iw3 < Win) tmp3 = mX(c, ih_g, iw3);
            val4 = make_float4(tmp0, tmp1, tmp2, tmp3);
          }
        }
        int base_idx = cc * (IH_TILE * TILE_OW) + ih_local * TILE_OW + ow_local0;
        *reinterpret_cast<float4*>(&sX[base_idx]) = val4;
      }
    } else {
      for (int idx = tid; idx < total_in; idx += NThreads) {
        int cc  = idx / (IH_TILE * TILE_OW);
        int rem = idx - cc * (IH_TILE * TILE_OW);
        int ih_local = rem / TILE_OW;
        int ow_local = rem - ih_local * TILE_OW;
        int c    = c_base + cc;
        int ow_g = ow_tile_base + ow_local;
        int iw_g = ow_g * stride - padding;
        int ih_g = min_ih + ih_local;
        T val = T(0);
        if (c < C && ow_g < Wout && iw_g >= 0 && iw_g < Win && ih_g >= 0 && ih_g < H) {
          val = mX(c, ih_g, iw_g);
        }
        sX[idx] = val;
      }
    }
    const int total_w = CcPerBlock * KChunk;
    for (int idx = tid; idx < total_w; idx += NThreads) {
      int cc = idx / KChunk;
      int kk = idx - cc * KChunk;
      int c  = c_base + cc;
      int k_global = k0 + kk;
      T wval = T(0);
      if (c < C && k_global < K) wval = mW(c, k_global);
      sW[idx] = wval;
    }
    __syncthreads();
    if (oh_valid) {
      #pragma unroll
      for (int kk = 0; kk < KChunk; ++kk) {
        if (kk >= kchunk_actual) break;
        int ih_local_index = tid_y * stride + kk * dilation;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int c = c_base + cc;
